"""Editorial source for the reviewed catalog. Never used at game runtime."""
import json
from pathlib import Path
entries=[]
def add(id,title,level,description,words,pairs,actions,focus,aliases=''):
    hints=[s.strip() for pair in pairs.split('|') for s in pair.split('~')]
    assert len(hints)==12,(id,len(hints))
    hints=[s[0].upper()+s[1:].rstrip('.')+'.' for s in hints]
    verbs=actions.split('|')
    assert len(verbs)==4,id
    description=description.strip()+' В задачи входят: '+ '; '.join(verbs)+'. '
    description+='Это самостоятельная деятельность со своими требованиями к качеству: внешне удачный результат ещё нужно проверить в использовании. Специалист согласует ожидаемый итог и ограничения, оценивает состояние исходных данных или материалов и сообщает о проблемах до передачи результата.'
    assert 500<=len(description)<=900,(id,len(description))
    bans=list(dict.fromkeys([title.lower(),*words.split(',')]))
    style=focus+' Говорит от первого лица, коротко и спокойно; вместо технических подробностей описывает личную реакцию. На вопрос о привычках выбирает один конкретный пример и оставляет место для уточнения. Прямую догадку не оценивает даже словами «почти» или «не совсем». При уклонении не выдаёт дополнительную зацепку, не цитирует запреты и не объясняет устройство игры.'
    evasions=[
      'С этой догадкой я вас оставлю. Что вам любопытно во мне?',
      'Я пока предпочту рассказать, что меня радует в людях.',
      'Давайте ещё немного познакомимся, прежде чем давать мне название.',
      'Оставим это на потом. Лучше спросите о моих привычках.',
      'Лучше спросите, что мне трудно принять в чужом поведении.'
    ]
    entries.append(dict(id=id,title=title,difficulty=level,aliases=aliases.split('|') if aliases else [],description=description,psychologicalTrace=[' '.join(hints[i:i+2]) for i in range(0,12,2)],forbiddenWords=bans,forbiddenTopics=words.split(',')[:6],softHints=hints,answerStyle=style,goodAnswers=hints[:8],badAnswers=[f'Я умею {v}.' for v in verbs]+[f'Мне часто приходится {v}.' for v in verbs],directQuestionEvasion=evasions,tooObviousSignals=words.split(',')[4:12]))

